    file_mtime = os.stat(filename).st_mtime
    for dirname, _, filenames in os.walk(directory):
        for filename in filenames:
            if filename.endswith(".pyc"):
                continue
            if _is_file_newer(os.path.join(dirname, filename), file_mtime):
